-- Code generated by togo. PostgreSQL schema fragment (converted from togo's SQLite-only template) — hand-editable; desired state for atlas migrate diff.
CREATE TABLE rum_samples (
    id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    app_id text NOT NULL,
    team_id text NOT NULL,
    path text NOT NULL,
    device text NOT NULL,
    effective_type text,
    lcp_ms real,
    cls real,
    inp_ms real,
    fcp_ms real,
    ttfb_ms real,
    created_at timestamptz NOT NULL DEFAULT now()
);

-- Hosbah (MH-575 H5): one raw Core Web Vitals sample per page-view lifecycle, posted once by the
-- beacon script (web/public served /rum.js — GET /rum.js is the static asset; internal/rum owns the
-- ingest). No IP address and no user-agent string are ever stored — device is only "mobile" or
-- "desktop" (from the viewport width) and effective_type is the Network Information API's coarse
-- class ("4g", "3g", …), never anything that alone or combined could re-identify a visitor.
-- Metrics are nullable: a browser that does not support a given PerformanceObserver entry (e.g. no
-- INP on older Safari) simply omits it; a page that unloads before LCP fires never got one either.
--
-- Percentiles are computed with percentile_cont(...) WITHIN GROUP directly over these raw rows
-- (internal/db/queries/rum_sample.sql) rather than a materialized hourly rollup: retention is only
-- 14 days (sweepRetention in internal/rum), the indexes below make every summary/timeseries/path
-- query an index range scan bounded by that window, and a self-hosted app's RUM volume is small
-- enough that this stays fast without the staleness and extra failure mode a rollup job would add.
-- If sample volume ever demands it, an hourly rollup table can be added later without changing this
-- one; nothing here precludes it.
ALTER TABLE rum_samples ADD CONSTRAINT rum_samples_device_check CHECK (device IN ('mobile', 'desktop'));
ALTER TABLE rum_samples ADD CONSTRAINT rum_samples_path_check CHECK (length(path) BETWEEN 1 AND 300);
CREATE INDEX rum_samples_app_created_idx ON rum_samples (team_id, app_id, created_at);
CREATE INDEX rum_samples_app_path_created_idx ON rum_samples (team_id, app_id, path, created_at);
CREATE INDEX rum_samples_created_idx ON rum_samples (created_at);
